import numpy as np


def linear(input: np.ndarray, weight: np.ndarray, bias: np.ndarray | None = None) -> np.ndarray:
    output = input @ weight.T
    if bias is not None:
        output = output + bias
    return output

import numpy as np


def mse_loss(y_hat: np.ndarray, y: np.ndarray) -> float:
    return float(np.mean((y_hat - y) ** 2))

import numpy as np


def gd_step(w: np.ndarray, b: float, dw: np.ndarray, db: float, lr: float) -> tuple[np.ndarray, float]:
    return w - lr * dw, b - lr * db

import numpy as np


def sigmoid(z: np.ndarray) -> np.ndarray:
    z = np.clip(z, -500, 500)
    return 1 / (1 + np.exp(-z))

import numpy as np


def bce_loss(p: np.ndarray, y: np.ndarray) -> float:
    p = np.clip(p, 1e-12, 1 - 1e-12)
    return float(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p)))

import numpy as np


def predict_labels(p: np.ndarray, threshold: float = 0.5) -> np.ndarray:
    return (p >= threshold).astype(int)

import numpy as np


def softmax(Z: np.ndarray) -> np.ndarray:
    Z_shift = Z - np.max(Z, axis=1, keepdims=True)
    exp_Z = np.exp(Z_shift)
    return exp_Z / np.sum(exp_Z, axis=1, keepdims=True)


def cce_loss(P: np.ndarray, y_indices: np.ndarray) -> float:
    n = P.shape[0]
    p_correct = np.clip(P[np.arange(n), y_indices], 1e-12, 1.0)
    return float(-np.mean(np.log(p_correct)))

import numpy as np


def weighted_bce_loss(p: np.ndarray, y: np.ndarray, class_weights: dict) -> float:
    p = np.clip(p, 1e-12, 1 - 1e-12)
    weights = np.where(y == 1, class_weights[1], class_weights[0])
    losses = weights * (y * np.log(p) + (1 - y) * np.log(1 - p))
    return float(-np.mean(losses))

import numpy as np


def bce_with_logits_loss(z: np.ndarray, y: np.ndarray) -> float:
    max_z_zero = np.maximum(z, 0)
    stable_log_term = np.log1p(np.exp(-np.abs(z)))
    per_sample = max_z_zero - z * y + stable_log_term
    return float(np.mean(per_sample))
